pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    function testFuzz_property(address from, address to, uint256 v) public {
        vm.assume(from != address(0));
        vm.assume(to != address(0));
        address[] memory tos = new address[](1);
        tos[0] = to;

        Recorder rec = new Recorder();
        bool ok;
        try c.transfer(from, address(rec), tos, v) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        assertTrue(ok && rec.getCount() == 1 && rec.getLastFrom() == from && rec.getLastTo() == to && rec.getLastAmount() == v);
    }
}

contract Recorder {
    uint256 public count;
    address public lastFrom;
    address public lastTo;
    uint256 public lastAmount;

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        count++;
        lastFrom = from;
        lastTo = to;
        lastAmount = amount;
        return true;
    }

    function getCount() external view returns (uint256) { return count; }
    function getLastFrom() external view returns (address) { return lastFrom; }
    function getLastTo() external view returns (address) { return lastTo; }
    function getLastAmount() external view returns (uint256) { return lastAmount; }
}
